// JT-ZERO v34: static accelerometer residual vs yaw using HIGHRES_IMU + ATTITUDE.
#define JTZERO_V10_NO_MAIN
#include "live_mono_imu_integrator_v10.cpp"
#undef JTZERO_V10_NO_MAIN
#include <array>
#include <fstream>
#include <iomanip>
namespace jtzero_v34 {
constexpr const char* kCsv34="/home/vio/jtzero_live_accel_yaw_static_v34.csv";
constexpr const char* kWindow34="JT-ZERO: СТАТИЧЕСКИЙ ACCEL/YAW v34";
constexpr int kPhases34=9; constexpr double kTargets34[kPhases34]={0,30,60,90,0,-30,-60,-90,0};
constexpr const char* kNames34[kPhases34]={"0_start","+30","+60","+90","0_mid","-30","-60","-90","0_final"};
constexpr double kYawTol34=1.5,kGyroStill34=.035,kAccNormTol34=.45; constexpr int kStableSamples34=100,kCollectSamples34=400;
struct Att34{bool valid=false;uint64_t us=0;double roll=0,pitch=0,yaw=0;Eigen::Matrix3d R=Eigen::Matrix3d::Identity();};
struct Row34{int phase=0;uint64_t us=0;double rel_yaw=0,roll=0,pitch=0,yaw=0;Eigen::Vector3d acc=Eigen::Vector3d::Zero(),gyro=Eigen::Vector3d::Zero(),expected=Eigen::Vector3d::Zero(),residual_body=Eigen::Vector3d::Zero();};
struct Stats34{int n=0;Eigen::Vector3d sum_acc=Eigen::Vector3d::Zero(),sum_res=Eigen::Vector3d::Zero(),ss_res=Eigen::Vector3d::Zero();double sum_roll=0,sum_pitch=0,sum_yaw=0;void add(const Row34&r){++n;sum_acc+=r.acc;sum_res+=r.residual_body;ss_res+=r.residual_body.cwiseProduct(r.residual_body);sum_roll+=r.roll;sum_pitch+=r.pitch;sum_yaw+=r.rel_yaw;}Eigen::Vector3d meanAcc()const{Eigen::Vector3d o=Eigen::Vector3d::Zero();if(n)o=sum_acc/double(n);return o;}Eigen::Vector3d meanRes()const{Eigen::Vector3d o=Eigen::Vector3d::Zero();if(n)o=sum_res/double(n);return o;}Eigen::Vector3d rmsRes()const{Eigen::Vector3d o=Eigen::Vector3d::Zero();if(n)o=(ss_res/double(n)).cwiseSqrt();return o;}};
static double normDeg34(double x){while(x>180)x-=360;while(x<-180)x+=360;return x;}
static void save34(const std::vector<Row34>&v){std::ofstream f(kCsv34);f<<std::fixed<<std::setprecision(9)<<"phase,phase_name,imu_us,rel_yaw_deg,fc_roll_deg,fc_pitch_deg,fc_yaw_deg,ax,ay,az,gx,gy,gz,exp_ax,exp_ay,exp_az,res_bx,res_by,res_bz\n";for(auto&r:v)f<<r.phase<<','<<kNames34[r.phase]<<','<<r.us<<','<<r.rel_yaw<<','<<r.roll<<','<<r.pitch<<','<<r.yaw<<','<<r.acc.x()<<','<<r.acc.y()<<','<<r.acc.z()<<','<<r.gyro.x()<<','<<r.gyro.y()<<','<<r.gyro.z()<<','<<r.expected.x()<<','<<r.expected.y()<<','<<r.expected.z()<<','<<r.residual_body.x()<<','<<r.residual_body.y()<<','<<r.residual_body.z()<<'\n';}
static void summary34(const std::array<Stats34,kPhases34>&s){std::cout<<std::fixed<<std::setprecision(9);auto b=s[0].meanRes();double mb=0,mw=0;std::cout<<"\nJT-ZERO STATIC ACCEL/YAW v34 RESULT\nbaseline residual @0 = ["<<b.transpose()<<"] m/s^2\n";for(int p=0;p<kPhases34;p++){auto m=s[p].meanRes(),d=m-b;double rr=s[p].n?s[p].sum_roll/s[p].n:0,pp=s[p].n?s[p].sum_pitch/s[p].n:0,yy=s[p].n?s[p].sum_yaw/s[p].n:0;auto w=jtzero_v10::fcRnedFlu(rr,pp,yy)*d;mb=std::max(mb,std::hypot(d.x(),d.y()));mw=std::max(mw,std::hypot(w.x(),w.y()));std::cout<<"\n"<<kNames34[p]<<" n="<<s[p].n<<" mean R/P/Yrel=["<<rr<<","<<pp<<","<<yy<<"]\n mean acc=["<<s[p].meanAcc().transpose()<<"]\n mean residual body=["<<m.transpose()<<"]\n RMS residual body=["<<s[p].rmsRes().transpose()<<"]\n delta vs 0 body=["<<d.transpose()<<"] |xy|="<<std::hypot(d.x(),d.y())<<"\n delta vs 0 world=["<<w.transpose()<<"] |xy|="<<std::hypot(w.x(),w.y())<<"\n";}auto c=s[8].meanRes()-b;std::cout<<"\nDecision helper:\n max yaw-dependent body XY delta="<<mb<<" m/s^2\n max yaw-dependent world XY delta="<<mw<<" m/s^2\n final 0 return body delta=["<<c.transpose()<<"] |xy|="<<std::hypot(c.x(),c.y())<<" m/s^2\n";}
static void hud34(const Att34&a,double y,const Eigen::Vector3d&acc,const Eigen::Vector3d&g,bool started,bool done,int ph,int stable,int collected){cv::Mat c(850,1300,CV_8UC3,cv::Scalar(15,15,15));cv::Scalar w(235,235,235),gr(80,220,80),ye(0,220,255);uiText(c,"JT-ZERO: СТАТИЧЕСКАЯ ПРОВЕРКА ACCEL ПО YAW v34",30,52,.68,w,2);if(!started){uiText(c,"УСТАНОВИТЕ СТЕНД В ИСХОДНЫЙ 0°",70,125,.65,ye,2);uiText(c,"SPACE — ЗАФИКСИРОВАТЬ НОЛЬ И НАЧАТЬ",70,180,.58,w,2);}else if(done){uiText(c,"ТЕСТ ЗАВЕРШЁН",70,125,.82,gr,3);}else{char t[128];snprintf(t,sizeof(t),"ЭТАП %d/9: YAW К %+.0f°",ph+1,kTargets34[ph]);uiText(c,t,70,125,.65,ye,2);uiText(c,stable>=kStableSamples34?"СТОП! СТЕНД НЕ ДВИГАТЬ — ИДЁТ СБОР":"ПОПАДИТЕ В ЗЕЛЁНУЮ ЗОНУ И ОСТАНОВИТЕСЬ",70,180,.52,stable>=kStableSamples34?gr:w,2);}cv::Mat q=c(cv::Rect(50,235,1200,540));drawBar(q,"YAW",y,-105,105,done?0:kTargets34[ph],kYawTol34,65);char t[256];snprintf(t,sizeof(t),"YAW %+.2f  ROLL %+.2f  PITCH %+.2f",y,a.roll,a.pitch);uiText(q,t,20,140,.48,w,1);snprintf(t,sizeof(t),"|gyro| %.4f   |acc| %.4f   стаб. %d/%d   собрано %d/%d",g.norm(),acc.norm(),stable,kStableSamples34,collected,kCollectSamples34);uiText(q,t,20,205,.44,w,1);uiText(q,"Маршрут: 0 → +30 → +60 → +90 → 0 → -30 → -60 → -90 → 0",20,455,.40,w,1);cv::imshow(kWindow34,c);}
}
int main(int argc,char**argv){google::InitGoogleLogging(argv[0]);int fd=-1;uint8_t sys=0,comp=0;mavlink_status_t st{};mavlink_message_t msg{};bool started=false,done=false;int ph=0,stable=0,collected=0;double ref=0;jtzero_v34::Att34 at;Eigen::Vector3d acc=Eigen::Vector3d::Zero(),gyro=Eigen::Vector3d::Zero();std::array<jtzero_v34::Stats34,jtzero_v34::kPhases34> stats;std::vector<jtzero_v34::Row34> rows;uint64_t last=0;try{fd=openSerial();std::cout<<"[MAV] waiting for HEARTBEAT...\n";int64_t dl=monotonicNs()+10000000000LL;while(monotonicNs()<dl&&!sys){pollfd p{fd,POLLIN,0};if(poll(&p,1,100)<=0)continue;uint8_t b[2048];ssize_t n=read(fd,b,sizeof(b));for(ssize_t i=0;i<n;i++)if(mavlink_parse_char(MAVLINK_COMM_0,b[i],&msg,&st)&&msg.msgid==MAVLINK_MSG_ID_HEARTBEAT){sys=msg.sysid;comp=msg.compid;break;}}if(!sys)throw std::runtime_error("HEARTBEAT timeout");requestRate(fd,sys,comp,MAVLINK_MSG_ID_ATTITUDE,100);requestRate(fd,sys,comp,MAVLINK_MSG_ID_HIGHRES_IMU,200);cv::namedWindow(jtzero_v34::kWindow34);int64_t nh=0;while(true){pollfd p{fd,POLLIN,0};poll(&p,1,5);if(p.revents&POLLIN){uint8_t b[8192];ssize_t n=read(fd,b,sizeof(b));if(n>0)for(ssize_t i=0;i<n;i++)if(mavlink_parse_char(MAVLINK_COMM_0,b[i],&msg,&st)){if(msg.msgid==MAVLINK_MSG_ID_ATTITUDE){mavlink_attitude_t a{};mavlink_msg_attitude_decode(&msg,&a);at.valid=true;at.roll=a.roll*180/kPi;at.pitch=a.pitch*180/kPi;at.yaw=a.yaw*180/kPi;at.R=jtzero_v10::fcRnedFlu(at.roll,at.pitch,at.yaw);}else if(msg.msgid==MAVLINK_MSG_ID_HIGHRES_IMU){mavlink_highres_imu_t h{};mavlink_msg_highres_imu_decode(&msg,&h);if(h.time_usec==last)continue;last=h.time_usec;acc={h.xacc,-h.yacc,-h.zacc};gyro={h.xgyro,-h.ygyro,-h.zgyro};if(started&&!done&&at.valid){double y=jtzero_v34::normDeg34(at.yaw-ref);bool ok=std::abs(jtzero_v34::normDeg34(y-jtzero_v34::kTargets34[ph]))<=jtzero_v34::kYawTol34&&gyro.norm()<=jtzero_v34::kGyroStill34&&std::abs(acc.norm()-9.81)<=jtzero_v34::kAccNormTol34;if(ok){if(stable<jtzero_v34::kStableSamples34)stable++;else{Eigen::Vector3d gw(0,0,9.81);jtzero_v34::Row34 r;r.phase=ph;r.us=h.time_usec;r.rel_yaw=y;r.roll=at.roll;r.pitch=at.pitch;r.yaw=at.yaw;r.acc=acc;r.gyro=gyro;r.expected=-at.R.transpose()*gw;r.residual_body=acc-r.expected;rows.push_back(r);stats[ph].add(r);if(++collected>=jtzero_v34::kCollectSamples34){std::cout<<"[STEP] "<<jtzero_v34::kNames34[ph]<<" collected.\n";stable=collected=0;if(++ph>=jtzero_v34::kPhases34){ph=8;done=true;std::cout<<"[TEST] completed.\n";}else std::cout<<"[NEXT] target "<<jtzero_v34::kTargets34[ph]<<" deg.\n";}}}else stable=0;}}}}if(monotonicNs()>=nh){double y=started&&at.valid?jtzero_v34::normDeg34(at.yaw-ref):0;jtzero_v34::hud34(at,y,acc,gyro,started,done,ph,stable,collected);nh=monotonicNs()+33333333LL;}int k=cv::waitKey(1)&255;if(k==27||k=='q'||k=='Q')break;if(k==' '&&!started&&at.valid){ref=at.yaw;started=true;std::cout<<"[ZERO] reference fixed.\n";}else if(k==' '&&done)break;}jtzero_v34::save34(rows);jtzero_v34::summary34(stats);std::cout<<"\nCSV: "<<jtzero_v34::kCsv34<<"\nOpen CSV:\n  code "<<jtzero_v34::kCsv34<<"\n";close(fd);cv::destroyAllWindows();return 0;}catch(const std::exception&e){if(fd>=0)close(fd);std::cerr<<"[FATAL] "<<e.what()<<"\n";return 1;}}
